3 // PSRAM\u3092\u642D\u8F09\n#define TOUCH_INT D7\n\n#include "camera_pins.h"\n\n// \u30E9\u30A6\u30F3\u30C9\u30C7\u30A3\u30B9\u30D7\u30EC\u30A4\u306E\u5E45\u3068\u9AD8\u3055\nconst int camera_width = 240;\nconst int camera_height = 240;\n\n// \u30D5\u30A1\u30A4\u30EB\u30AB\u30A6\u30F3\u30BF\u30FC\nint imageCount = 1;\nbool camera_sign = false;          // \u30AB\u30E1\u30E9\u306E\u72B6\u614B\u3092\u78BA\u8A8D\nbool sd_sign = false;              // SD\u30AB\u30FC\u30C9\u306E\u72B6\u614B\u3092\u78BA\u8A8D\n\nTFT_eSPI tft = TFT_eSPI();\n\n// SD\u30AB\u30FC\u30C9\u3078\u306E\u30D5\u30A1\u30A4\u30EB\u66F8\u304D\u8FBC\u307F\nvoid writeFile(fs::FS &fs, const char * path, uint8_t * data, size_t len){\n    Serial.printf("\u30D5\u30A1\u30A4\u30EB\u3092\u66F8\u304D\u8FBC\u307F\u4E2D: %s\\n", path);\n\n    File file = fs.open(path, FILE_WRITE);\n    if(!file){\n        Serial.println("\u30D5\u30A1\u30A4\u30EB\u3092\u958B\u304F\u306E\u306B\u5931\u6557\u3057\u307E\u3057\u305F");\n        return;\n    }\n    if(file.write(data, len) == len){\n        Serial.println("\u30D5\u30A1\u30A4\u30EB\u304C\u66F8\u304D\u8FBC\u307E\u308C\u307E\u3057\u305F");\n    } else {\n        Serial.println("\u66F8\u304D\u8FBC\u307F\u306B\u5931\u6557\u3057\u307E\u3057\u305F");\n    }\n    file.close();\n}\n\nbool display_is_pressed(void)\n{\n    if(digitalRead(TOUCH_INT) != LOW) {\n        delay(3);\n        if(digitalRead(TOUCH_INT) != LOW)\n        return false;\n    }\n    return true;\n}\n\nvoid setup() {\n  // \u521D\u56DE\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\n  Serial.begin(115200);\n//  while(!Serial);\n\n  // \u30AB\u30E1\u30E9\u306E\u30D4\u30F3\u8A2D\u5B9A\n  camera_config_t config;\n  config.ledc_channel = LEDC_CHANNEL_0;\n  config.ledc_timer = LEDC_TIMER_0;\n  config.pin_d0 = Y2_GPIO_NUM;\n  config.pin_d1 = Y3_GPIO_NUM;\n  config.pin_d2 = Y4_GPIO_NUM;\n  config.pin_d3 = Y5_GPIO_NUM;\n  config.pin_d4 = Y6_GPIO_NUM;\n  config.pin_d5 = Y7_GPIO_NUM;\n  config.pin_d6 = Y8_GPIO_NUM;\n  config.pin_d7 = Y9_GPIO_NUM;\n  config.pin_xclk = XCLK_GPIO_NUM;\n  config.pin_pclk = PCLK_GPIO_NUM;\n  config.pin_vsync = VSYNC_GPIO_NUM;\n  config.pin_href = HREF_GPIO_NUM;\n  config.pin_sscb_sda = SIOD_GPIO_NUM;\n  config.pin_sscb_scl = SIOC_GPIO_NUM;\n  config.pin_pwdn = PWDN_GPIO_NUM;\n  config.pin_reset = RESET_GPIO_NUM;\n  config.xclk_freq_hz = 20000000;\n//  config.frame_size = FRAMESIZE_UXGA;\n  config.frame_size = FRAMESIZE_240X240;\n//  config.pixel_format = PIXFORMAT_JPEG; // \u30B9\u30C8\u30EA\u30FC\u30DF\u30F3\u30B0\u7528\n  config.pixel_format = PIXFORMAT_RGB565;\n  config.grab_mode = CAMERA_GRAB_WHEN_EMPTY;\n  config.fb_location = CAMERA_FB_IN_PSRAM;\n  config.jpeg_quality = 12;\n  config.fb_count = 1;\n  \n  // PSRAM IC\u304C\u5B58\u5728\u3059\u308B\u5834\u5408\u3001UXGA\u89E3\u50CF\u5EA6\u3068\u9AD8\u54C1\u8CEAJPEG\u3067\u521D\u671F\u5316\n  if(config.pixel_format == PIXFORMAT_JPEG){\n    if(psramFound()){\n      config.jpeg_quality = 10;\n      config.fb_count = 2;\n      config.grab_mode = CAMERA_GRAB_LATEST;\n    } else {\n      // PSRAM\u304C\u5229\u7528\u3067\u304D\u306A\u3044\u5834\u5408\u3001\u30D5\u30EC\u30FC\u30E0\u30B5\u30A4\u30BA\u3092\u5236\u9650\n      config.frame_size = FRAMESIZE_SVGA;\n      config.fb_location = CAMERA_FB_IN_DRAM;\n    }\n  } else {\n    // \u9854\u8A8D\u8B58/\u691C\u51FA\u306B\u6700\u9069\u306A\u30AA\u30D7\u30B7\u30E7\u30F3\n    config.frame_size = FRAMESIZE_240X240;\n#if CONFIG_IDF_TARGET_ESP32S3\n    config.fb_count = 2;\n#endif\n  }\n\n  // \u30AB\u30E1\u30E9\u521D\u671F\u5316\n  esp_err_t err = esp_camera_init(&config);\n  if (err != ESP_OK) {\n    Serial.printf("\u30AB\u30E1\u30E9\u521D\u671F\u5316\u306B\u5931\u6557\u3057\u307E\u3057\u305F\u3002\u30A8\u30E9\u30FC\u30B3\u30FC\u30C9: 0x%x", err);\n    return;\n  }\n  Serial.println("\u30AB\u30E1\u30E9\u6E96\u5099\u5B8C\u4E86");\n  camera_sign = true; // \u30AB\u30E1\u30E9\u521D\u671F\u5316\u30C1\u30A7\u30C3\u30AF\u5408\u683C\n\n  // \u30C7\u30A3\u30B9\u30D7\u30EC\u30A4\u521D\u671F\u5316\n  tft.init();\n  tft.setRotation(1);\n  tft.fillScreen(TFT_WHITE);\n\n  // SD\u30AB\u30FC\u30C9\u521D\u671F\u5316\n  if(!SD.begin(D2)){\n    Serial.println("\u30AB\u30FC\u30C9\u306E\u30DE\u30A6\u30F3\u30C8\u306B\u5931\u6557\u3057\u307E\u3057\u305F");\n    return;\n  }\n  uint8_t cardType = SD.cardType();\n\n  // SD\u30AB\u30FC\u30C9\u306E\u7A2E\u985E\u3092\u78BA\u8A8D\n  if(cardType == CARD_NONE){\n    Serial.println("SD\u30AB\u30FC\u30C9\u304C\u63A5\u7D9A\u3055\u308C\u3066\u3044\u307E\u305B\u3093");\n    return;\n  }\n\n  Serial.print("SD\u30AB\u30FC\u30C9\u306E\u7A2E\u985E: ");\n  if(cardType == CARD_MMC){\n    Serial.println("MMC");\n  } else if(cardType == CARD_SD){\n    Serial.println("SDSC");\n  } else if(cardType == CARD_SDHC){\n    Serial.println("SDHC");\n  } else {\n    Serial.println("\u4E0D\u660E");\n  }\n\n  sd_sign = true; // SD\u521D\u671F\u5316\u30C1\u30A7\u30C3\u30AF\u5408\u683C\n\n}\n\nvoid loop() {\n  if( sd_sign && camera_sign){\n\n    // \u5199\u771F\u3092\u64AE\u5F71\n    camera_fb_t *fb = esp_camera_fb_get();\n    if (!fb) {\n      Serial.println("\u30AB\u30E1\u30E9\u30D5\u30EC\u30FC\u30E0\u30D0\u30C3\u30D5\u30A1\u306E\u53D6\u5F97\u306B\u5931\u6557\u3057\u307E\u3057\u305F");\n      return;\n    }\n    \n    if(display_is_pressed()){\n      Serial.println("\u30C7\u30A3\u30B9\u30D7\u30EC\u30A4\u304C\u30BF\u30C3\u30C1\u3055\u308C\u307E\u3057\u305F");\n      char filename[32];\n      sprintf(filename, "/image%d.jpg", imageCount);\n      // \u5199\u771F\u3092\u30D5\u30A1\u30A4\u30EB\u306B\u4FDD\u5B58\n      writeFile(SD, filename, fb->buf, fb->len);\n      Serial.printf("\u5199\u771F\u3092\u4FDD\u5B58\u3057\u307E\u3057\u305F\uFF1A%s\\n", filename);\n      imageCount++;\n    }\n  \n    // JPEG\u753B\u50CF\u3092\u30C7\u30B3\u30FC\u30C9\n    uint8_t* buf = fb->buf;\n    uint32_t len = fb->len;\n    tft.startWrite();\n    tft.setAddrWindow(0, 0, camera_width, camera_height);\n    tft.pushColors(buf, len);\n    tft.endWrite();\n      \n    // \u30A4\u30E1\u30FC\u30B8\u30D0\u30C3\u30D5\u30A1\u3092\u89E3\u653E\n    esp_camera_fb_return(fb);\n\n    delay(10);\n  }\n}\n'})}),"\n",(0,r.jsx)(e.p,{children:"XIAO ESP32S3 Sense \u306B\u30D7\u30ED\u30B0\u30E9\u30E0\u3092\u30A2\u30C3\u30D7\u30ED\u30FC\u30C9\u3057\u307E\u3059\u3002\u30A2\u30C3\u30D7\u30ED\u30FC\u30C9\u304C\u6210\u529F\u3057\u305F\u5F8C\u306B\u753B\u9762\u304C\u70B9\u706F\u3057\u306A\u3044\u5834\u5408\u306F\u3001XIAO \u306E\u30EA\u30BB\u30C3\u30C8\u30DC\u30BF\u30F3\u3092\u30AF\u30EA\u30C3\u30AF\u3059\u308B\u5FC5\u8981\u304C\u3042\u308B\u304B\u3082\u3057\u308C\u307E\u305B\u3093\u3002\u305D\u306E\u5F8C\u3001\u30E9\u30A6\u30F3\u30C9\u30C7\u30A3\u30B9\u30D7\u30EC\u30A4\u306B\u30EA\u30A2\u30EB\u30BF\u30A4\u30E0\u3067\u76E3\u8996\u753B\u9762\u304C\u8868\u793A\u3055\u308C\u307E\u3059\u3002\u753B\u9762\u306E\u4EFB\u610F\u306E\u5834\u6240\u3092\u30AF\u30EA\u30C3\u30AF\u3059\u308B\u3068\u3001\u753B\u50CF\u304C\u8A18\u9332\u3055\u308C\u3001microSD\u30AB\u30FC\u30C9\u306B\u4FDD\u5B58\u3055\u308C\u307E\u3059\u3002"}),"\n",(0,r.jsx)("div",{style:{textAlign:"center"},children:(0,r.jsx)("img",{src:"https://files.seeedstudio.com/wiki/SeeedStudio-XIAO-ESP32S3/img/95.gif",style:{width:800,height:"auto"}})}),"\n",(0,r.jsx)(e.h3,{id:"\u30D7\u30ED\u30B0\u30E9\u30E0\u306E\u6CE8\u91C8-1",children:"\u30D7\u30ED\u30B0\u30E9\u30E0\u306E\u6CE8\u91C8"}),"\n",(0,r.jsxs)(e.p,{children:["\u30AB\u30E1\u30E9\u3068microSD\u30AB\u30FC\u30C9\u306E\u8A2D\u5B9A\u306F\u524D\u306E\u5185\u5BB9\u3067\u8AAC\u660E\u6E08\u307F\u306A\u306E\u3067\u3001\u3053\u3053\u3067\u306F\u7E70\u308A\u8FD4\u3057\u307E\u305B\u3093\u3002microSD\u30AB\u30FC\u30C9\u306E\u4F7F\u7528\u65B9\u6CD5\u306B\u3064\u3044\u3066\u306F\u3001",(0,r.jsx)(e.a,{href:"https://wiki.seeedstudio.com/ja/xiao_esp32s3_sense_filesystem",children:"XIAO ESP32S3 Sense \u30D5\u30A1\u30A4\u30EB\u30B7\u30B9\u30C6\u30E0"})," Wiki \u3092\u53C2\u7167\u3057\u3066\u4F7F\u7528\u65B9\u6CD5\u3092\u5B66\u3093\u3067\u304F\u3060\u3055\u3044\u3002"]})